contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 waitSeconds) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(waitSeconds > 0, "waitSeconds must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;

        if (waitSeconds > block.timestamp) {
            waitSeconds = waitSeconds - block.timestamp;
        } else {
            waitSeconds = 1;
        }

        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature(""));

        if (success) {
            assert(c.pastBlockTime() > beforeTime && address(c).balance >= beforeBal);
        } else {
            assert(c.pastBlockTime() == beforeTime);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount, uint256 targetTimestamp) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeTime = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();

        assert(
            reverted
                ? (amount != 10 ether || targetTimestamp <= beforeTime) && afterTime == beforeTime
                : amount == 10 ether && targetTimestamp > beforeTime && afterTime == targetTimestamp
        );
    }
}

