contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint nonIncreasingDelta, bool wrongValue) public payable {
        require(address(this).balance >= 10 ether);

        // Establish a non-zero pastBlockTime that is relatively large.
        c.fallback{value: 10 ether}();
        uint beforeTime = c.pastBlockTime();
        require(beforeTime != 0);

        // Choose a timestamp for the deciding call; non-increasing can be requested.
        uint chosen = nonIncreasingDelta == 0 ? beforeTime : beforeTime - nonIncreasingDelta;
        uint target = nonIncreasingDelta == 0 ? beforeTime : chosen;
        require(!wrongValue || target > beforeTime);

        uint beforeTs = block.timestamp;
        // Skip forward when we want the deciding call to succeed.
        if (!wrongValue) {
            require(target > block.timestamp);
            uint gap = target - block.timestamp;
            if (gap > 0) {
                uint target;
                target = beforeTs + gap;
                require(false); // unreachable; timestamp cannot be advanced in a test
            }
        }

        uint amount = wrongValue ? 1 ether : 10 ether;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        bool expectedSuccess = !wrongValue && block.timestamp > beforeTime;
        assert(reverted != expectedSuccess);
        if (reverted) {
            assert(afterTime == beforeTime);
        } else {
            assert(afterTime == block.timestamp);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint delta) public payable {
        // Ensure this contract can fund a correct fallback call.
        require(address(this).balance >= 10 ether);

        // Establish a known pastBlockTime via a valid call.
        c.fallback{value: 10 ether}();
        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // The deciding call must have block.timestamp > pastBlockTime to succeed.
        // We cannot control block.timestamp directly, so success is only possible
        // when the current timestamp is already greater than beforeTime.
        bool canSucceed = block.timestamp > beforeTime;

        // If the caller requests a non-10-ether value, it will always revert.
        // Otherwise, if the timestamp is not strictly greater, it will revert too.
        bool shouldRevert = (amount != 10 ether) || !canSucceed;

        // The call value to actually send: use the requested amount, but avoid
        // sending the test contract's entire balance when amount is huge.
        uint sendAmount = amount > address(this).balance ? address(this).balance : amount;

        // If we cannot cover a correct 10 ether call, the success branch is impossible.
        if (!shouldRevert && address(this).balance < 10 ether) {
            shouldRevert = true;
        }

        bool reverted;
        try c.fallback{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        if (shouldRevert) {
            // Reverts must not change the stored timestamp.
            assert(reverted);
            assert(afterTime == beforeTime);
        } else {
            // A successful call must update pastBlockTime to the call's timestamp
            // and the call must not have reverted.
            assert(!reverted);
            assert(afterTime == block.timestamp);
            assert(afterTime > beforeTime);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
