    function run(uint amount) public payable {
        require(address(this).balance >= 10 ether);

        // Setup: one valid fallback call establishes a known pastBlockTime.
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1);

        uint beforeTime = c.pastBlockTime();

        // Decide how much to send for the deciding call. It must be from a parameter.
        // To make the rule general, we use `amount`, but cap it so the test can always
        // send it without underflow / insufficient balance.
        uint sendAmount = amount;
        if (sendAmount > address(this).balance) {
            sendAmount = address(this).balance;
        }

        bool reverted;
        (bool success, ) = address(c).call{value: sendAmount}("");
        reverted = !success;

        uint afterTime = c.pastBlockTime();

        // The fallback should succeed exactly when it sends 10 ether and the timestamp
        // is strictly greater than the stored one. Otherwise it must revert and leave
        // the stored timestamp untouched.
        bool expectedSuccess = (sendAmount == 10 ether) && (block.timestamp > beforeTime);

        if (expectedSuccess) {
            assert(!reverted);
            assert(afterTime == block.timestamp);
            assert(afterTime > beforeTime);
        } else {
            assert(reverted);
            assert(afterTime == beforeTime);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, bool doUpdate) public payable {
        require(address(this).balance >= 20 ether);

        // Setup: one successful fallback call if possible, to establish pastBlockTime
        bool setupSuccess;
        if (doUpdate) {
            (setupSuccess, ) = address(c).call{value: 10 ether}("");
        }
        require(setupSuccess || !doUpdate);

        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Determine the actual amount to send
        uint sendAmount = amount % (20 ether);
        if (sendAmount == 0) sendAmount = 1 wei;

        // Ensure we have enough balance for sendAmount, otherwise use max available
        if (sendAmount > address(this).balance) {
            sendAmount = address(this).balance;
        }

        // The deciding call: call fallback with the chosen amount
        // This is the top-level state-changing call
        bool reverted;
        (bool success, ) = address(c).call{value: sendAmount}("");
        reverted = !success;

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // The general rule: the fallback succeeds iff it sends exactly 10 ether and the timestamp is strictly greater than the stored pastBlockTime.
        // On success, pastBlockTime becomes the current timestamp and c's balance increases by 10 ether.
        // On failure, pastBlockTime and c's balance remain unchanged.
        bool expectedSuccess = (sendAmount == 10 ether) && (block.timestamp > beforeTime);

        assert(
            (expectedSuccess && (!reverted) && (afterTime == block.timestamp) && (afterBalance == beforeBalance + 10 ether)) ||
            (!expectedSuccess && reverted && (afterTime == beforeTime) && (afterBalance == beforeBalance))
        );
    }

    receive() external payable {}
}

