contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint64 firstTs, uint64 secondTs) public payable {
        // Ensure the test contract can fund two 10 ether calls.
        require(address(this).balance >= 40 ether);

        // We want two calls with controlled timestamps.  Since we cannot
        // manipulate block.timestamp directly, we call twice in the same
        // transaction: the first call always succeeds (contract starts with
        // pastBlockTime == 0) and sets pastBlockTime to block.timestamp.
        // The second call then tests the require(block.timestamp > pastBlockTime)
        // because the timestamp is the same.
        require(firstTs == 0 && secondTs == 0); // placeholder to keep params used

        bool firstReverted;
        try c.fallback{value: 10 ether}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 beforeBalance = address(c).balance;
        uint256 beforeTime = c.pastBlockTime();

        bool secondReverted;
        try c.fallback{value: 10 ether}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterTime = c.pastBlockTime();

        // Rule: the first call should succeed (initial pastBlockTime == 0 and
        // block.timestamp > 0).  If it did succeed, it set pastBlockTime to the
        // current block timestamp.  The second call, sent in the same block,
        // sees the same timestamp, so block.timestamp is NOT strictly greater
        // than pastBlockTime and the second call MUST revert.  Therefore:
        //   (!firstReverted) and secondReverted and (afterTime == beforeTime)
        // (no timestamp change on the reverted call), and the contract's balance
        // after the second call is exactly 10 ether (from the first successful call).
        assert(
            firstReverted == false &&
            secondReverted == true &&
            afterTime == beforeTime &&
            address(c).balance == 10 ether
        );
    }

    receive() external payable {}
}

