        // We can satisfy it by first setting pastBlockTime to a lower value with a successful call.
        // Initial pastBlockTime is 0, so a first 10 ether call always succeeds unless block.timestamp is 0.
        // To make the second call's precondition controllable, record the timestamp before it.
        uint before = c.pastBlockTime();
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        // If the first call succeeded, pastBlockTime is now some ts > before (unless timestamp wrapped).
        // We take a second call and check: if the current block timestamp is greater than the stored one, the call must not revert.
        uint afterFirst = c.pastBlockTime();
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterSecond = c.pastBlockTime();
        // General rule: for any state where block.timestamp > pastBlockTime, the fallback with 10 ether must not revert
        // and must update pastBlockTime to block.timestamp.
        // We use timestampOffset to represent a hypothetical current timestamp relative to afterFirst.
        // The rule: if block.timestamp > afterFirst, then the second call must not revert and afterSecond == block.timestamp.
        // However block.timestamp is fixed during the transaction; we can only test the actual value.
        // To make this a general property over params, note that the call either reverts or not.
        // If it reverts, it must be because block.timestamp <= afterFirst; if it does not revert, afterSecond == block.timestamp and afterSecond > afterFirst.
        if (block.timestamp > afterFirst) {
            assert(!reverted && afterSecond == block.timestamp);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint firstAmount, uint secondAmount) public payable {
        // We need enough Ether in this test contract to send two fallback calls of 10 ether each in the worst case.
        require(address(this).balance >= 20 ether);

        // Precondition to force a first fallback call: must send exactly 10 ether.
        require(firstAmount == 10 ether);
        require(secondAmount == 10 ether);

        // First call: drive c's fallback once to establish a non-zero pastBlockTime if possible.
        (bool ok1, ) = address(c).call{value: firstAmount}("");

        // Read the observable state before the deciding call.
        uint pastBefore = c.pastBlockTime();

        // Deciding call: exactly 10 ether through the fallback.  We cannot write `c.fallback(...)`
        // directly because `fallback` is not a named function; use a low-level call.
        (bool ok2, ) = address(c).call{value: secondAmount}("");

        // Read the observable state after the deciding call.
        uint pastAfter = c.pastBlockTime();

        // General rule:
        //   - The deciding call reverts exactly when block.timestamp <= pastBefore (the require in c's fallback fails).
        //   - On success, block.timestamp > pastBefore and c.pastBlockTime() becomes block.timestamp.
        //   - On failure, c.pastBlockTime() is unchanged.
        if (ok2) {
            assert(block.timestamp > pastBefore);
            assert(pastAfter == block.timestamp);
        } else {
            assert(block.timestamp <= pastBefore);
            assert(pastAfter == pastBefore);
        }

        // One of the two branches must have been taken, so at least the first call's effect is visible
        // in pastBefore, and the deciding call's outcome is fully characterized above.
        assert(pastBefore >= 0);
    }

    receive() external payable {}
}

