contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, uint newTimestamp) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "not enough balance");

        // Ensure the sent timestamp cannot be lower than the existing one before the deciding call.
        uint oldTimestamp = c.pastBlockTime();
        require(newTimestamp > oldTimestamp, "newTimestamp must be greater than pastBlockTime");

        // The test cannot directly set block.timestamp, so drive the fallback with a timestamp that is either
        // the current one (allowed) or one that is strictly greater (allowed) by using the actual block.timestamp
        // through a low-level call on the contract address. The public entry is the fallback, so we call it directly.
        bool reverted;
        (bool success, ) = address(c).call{value: amount}("");
        reverted = !success;

        uint newPastBlockTime = c.pastBlockTime();
        uint contractBalance = address(c).balance;

        // General rule: sending exactly 10 ether to the fallback succeeds exactly when the current
        // block.timestamp is strictly greater than the pastBlockTime before the call. In that case,
        // pastBlockTime updates to the call's timestamp (which equals block.timestamp) and c holds
        // exactly the sent amount (plus any balance it already had, but it starts empty and only
        // the test sends Ether). For the test contract, the only possible Ether source is this call.
        // We cannot read block.timestamp directly in the assert, but the precondition above ensures
        // newTimestamp is a valid future timestamp relative to oldTimestamp. The rule uses that as
        // a proxy: if the call succeeds, pastBlockTime must equal newTimestamp only if the test
        // somehow could set it, but since block.timestamp is used, we instead assert the observable
        // invariant that on success pastBlockTime is greater than oldTimestamp and c's balance equals amount.
        if (reverted) {
            assert(newPastBlockTime == oldTimestamp);
        } else {
            assert(newPastBlockTime > oldTimestamp && contractBalance == amount);
        }
    }

    fallback() external payable {}
}

