contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 timestamp, uint256 blockNumber) public payable {
        // Precondition: exactly 10 ether must be sent, and enough balance must exist.
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Precompute the expected outcome based on the current public state and inputs.
        uint256 past = c.pastBlockTime();
        bool expectRevert = (timestamp <= past) || (blockNumber % 15 == 0);

        // In a real chain, block.timestamp and block.number are set by the environment.
        // This test assumes the checker will supply the current block values matching the inputs.
        // We use them to drive the call through the public fallback entry point.
        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the fallback reverts exactly when the timestamp is not strictly
        // greater than the previously recorded one, or when the current block number is
        // a multiple of 15 (which would trigger a transfer and thus require the call to
        // not revert). Conversely, it succeeds only when both conditions are false.
        assert(reverted == expectRevert);
    }

    receive() external payable {}
}

