                assert(afterC == 0);
                assert(afterThis == beforeThis + beforeC);
            } else {
                assert(afterC == beforeC + 10 ether);
                assert(afterThis == beforeThis - 10 ether);
            }
        }
    }

    receive() external payable {}
}

