        require(address(this).balance >= sendAmount, "insufficient balance");

        uint oldPastBlockTime = c.pastBlockTime();

        if (advanceTime) {
            // Ensure the precondition for a successful call is satisfiable from the test's state.
            require(block.timestamp > oldPastBlockTime, "timestamp already past");
