        }

        bool reverted;
        try c.fallback{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(sendAmount == 10 ether && block.timestamp > oldPastBlockTime);
        } else {
            assert(sendAmount != 10 ether || !(block.timestamp > oldPastBlockTime));
        }
    }

    receive() external payable {}
}

